import Mathlib
open Topology

variable {I : Type*} [DecidableEq I] {S : I → Type*}

def StrictlyDominates (u : (∀ i, S i) → I → ℝ) (player : I) (si si' : S player) : Prop :=
  ∀ (s : ∀ i, S i), u (Function.update s player si) player > u (Function.update s player si') player

import Mathlib

variable {Player : Type} [DecidableEq Player] {S : Player → Type}

def StrictlyDominated (u : (∀ i, S i) → ℝ) (i : Player) (si : S i) : Prop :=
  ∃ si' : S i, ∀ σ : ∀ j, S j, u (Function.update σ i si') > u (Function.update σ i si)
